style.css:
/* Midnight CD — Spotify */

:root {
  /* Change these values to customise the palette */
  --my-bg: #101014;
  --my-panel: #18181e;
  --my-silver: #b9bac2;
  --my-muted: #777984;
  --my-purple: #7565a8;
  --my-blue: #526b91;
  --my-border: #303139;
}

/* Main background */
body {
  background: var(--my-bg) !important;
  color: var(--my-silver) !important;
  font-family: Arial, Helvetica, sans-serif !important;
}

/* Main Spotify panels */
main,
aside,
[role="main"] {
  background-color: var(--my-panel) !important;
  color: var(--my-silver) !important;
}

/* Buttons — retro hardware styling */
button {
  border: 1px solid var(--my-border) !important;
  border-radius: 4px !important;
  box-shadow: inset 0 1px 2px rgba(255,255,255,0.08) !important;
  transition: background-color 0.2s ease !important;
}

/* Album artwork */
img {
  border-radius: 3px !important;
}

/* Links */
a {
  color: var(--my-silver) !important;
  transition: color 0.2s ease !important;
}

/* Hover effects */
button:hover,
a:hover {
  color: var(--my-purple) !important;
}

/* Selected navigation */
[aria-selected="true"] {
  color: var(--my-purple) !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 10px !important;
}

::-webkit-scrollbar-track {
  background: var(--my-bg) !important;
}

::-webkit-scrollbar-thumb {
  background: #41424a !important;
  border-radius: 3px !important;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--my-purple) !important;
}

/* Subtle retro blue-purple accents */
button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--my-blue) !important;
  outline-offset: 2px !important;
}
